import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"64、【未济】 坎下离上","description":"横渠易说 - 64、【未济】 坎下离上","frontmatter":{"title":"64、【未济】 坎下离上","description":"横渠易说 - 64、【未济】 坎下离上"},"headers":[],"relativePath":"zh/classics/hengqu/066.md","filePath":"zh/classics/hengqu/066.md"}'),l={name:"zh/classics/hengqu/066.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_64、【未济】-坎下离上" tabindex="-1">64、【未济】 坎下离上 <a class="header-anchor" href="#_64、【未济】-坎下离上" aria-label="Permalink to “64、【未济】 坎下离上”">​</a></h1><h3 id="彖曰-未济亨-柔得中也。-小狐汔济-未出中也-濡其尾无攸利-不续终也-虽不当位-刚柔应也。" tabindex="-1">彖曰：“未济亨”，柔得中也。“小狐汔济”，未出中也，“濡其尾无攸利”，不续终也，虽不当位，刚柔应也。 <a class="header-anchor" href="#彖曰-未济亨-柔得中也。-小狐汔济-未出中也-濡其尾无攸利-不续终也-虽不当位-刚柔应也。" aria-label="Permalink to “彖曰：“未济亨”，柔得中也。“小狐汔济”，未出中也，“濡其尾无攸利”，不续终也，虽不当位，刚柔应也。”">​</a></h3><h3 id="象曰-火在水上-未济-君子以慎辨物居方。" tabindex="-1">象曰：火在水上，未济，君子以慎辨物居方。 <a class="header-anchor" href="#象曰-火在水上-未济-君子以慎辨物居方。" aria-label="Permalink to “象曰：火在水上，未济，君子以慎辨物居方。”">​</a></h3><h3 id="初六-濡其尾-吝。-象曰-濡其尾-亦不知极也。" tabindex="-1">初六，濡其尾，吝。 象曰：“濡其尾”，亦不知极也。 <a class="header-anchor" href="#初六-濡其尾-吝。-象曰-濡其尾-亦不知极也。" aria-label="Permalink to “初六，濡其尾，吝。 象曰：“濡其尾”，亦不知极也。”">​</a></h3><h3 id="九二-曳其轮-贞吉。-象曰-九二贞吉-中以行正也。" tabindex="-1">九二，曳其轮，贞吉。 象曰：九二贞吉，中以行正也。 <a class="header-anchor" href="#九二-曳其轮-贞吉。-象曰-九二贞吉-中以行正也。" aria-label="Permalink to “九二，曳其轮，贞吉。 象曰：九二贞吉，中以行正也。”">​</a></h3><h3 id="六三-未济征凶-利涉大川。-象曰-未济征凶-位不当也。" tabindex="-1">六三，未济征凶，利涉大川。 象曰：“未济征凶”，位不当也。 <a class="header-anchor" href="#六三-未济征凶-利涉大川。-象曰-未济征凶-位不当也。" aria-label="Permalink to “六三，未济征凶，利涉大川。 象曰：“未济征凶”，位不当也。”">​</a></h3><p>有强援于上，故利涉大川，非义躁进，凶之道也。</p><h3 id="九四-贞吉悔亡。震用伐鬼方-三年有赏于大国。-象曰-贞吉悔亡-志行也。" tabindex="-1">九四，贞吉悔亡。震用伐鬼方，三年有赏于大国。 象曰：“贞吉悔亡”，志行也。 <a class="header-anchor" href="#九四-贞吉悔亡。震用伐鬼方-三年有赏于大国。-象曰-贞吉悔亡-志行也。" aria-label="Permalink to “九四，贞吉悔亡。震用伐鬼方，三年有赏于大国。 象曰：“贞吉悔亡”，志行也。”">​</a></h3><p>刚阳之德，迫近至尊，非正而吉，悔所招也。初处险中，叛而未一，奋动讨伐，其势必克，堪上之任，是以有赏。</p><h3 id="六五-贞吉无悔-君子之光-有孚-吉。-象曰-君子之光-其晖吉也。" tabindex="-1">六五，贞吉无悔，君子之光，有孚，吉。 象曰：“君子之光”，其晖吉也。 <a class="header-anchor" href="#六五-贞吉无悔-君子之光-有孚-吉。-象曰-君子之光-其晖吉也。" aria-label="Permalink to “六五，贞吉无悔，君子之光，有孚，吉。 象曰：“君子之光”，其晖吉也。”">​</a></h3><h3 id="上九-有孚于饮酒-无咎。濡其首-有孚失是。-象曰-饮酒濡首-亦不知节也。" tabindex="-1">上九，有孚于饮酒，无咎。濡其首，有孚失是。 象曰：饮酒濡首，亦不知节也。 <a class="header-anchor" href="#上九-有孚于饮酒-无咎。濡其首-有孚失是。-象曰-饮酒濡首-亦不知节也。" aria-label="Permalink to “上九，有孚于饮酒，无咎。濡其首，有孚失是。 象曰：饮酒濡首，亦不知节也。”">​</a></h3><p>饮酒而至于濡首，不节之甚也，其必失此乐也有孚。</p>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
